"""Generate ghouls_data.h: the PSID's load address and image, byte for byte."""

from header import cli
from sidtrace import psid_parts


def generate(psid):
    """Return header text defining IMAGE_ORG and the IMAGE initializer."""
    load, _, _, image = psid_parts(psid)
    body = ",".join(f"0x{b:02x}" for b in image)
    return (
        "/* generated by gen_ghouls.py */\n"
        f"#define IMAGE_ORG 0x{load:04x}\n#define IMAGE {body}\n"
    )


def main(argv=None):
    """CLI entry point."""
    cli(generate, __doc__, argv)


if __name__ == "__main__":
    main()
